import networkx as nx
import random

def check_girth_and_edges(n, m):
    while True:
        # Create a bipartite graph
        # V1 = {0, ..., 8}, V2 = {9, ..., 18}
        edges = set()
        while len(edges) < m:
            u = random.randint(0, 8)
            v = random.randint(9, 18)
            if u != v:
                edges.add(tuple(sorted((u, v))))

        G = nx.Graph()
        G.add_nodes_from(range(n))
        G.add_edges_from(edges)

        # Check girth
        try:
            girth = nx.girth(G)
        except:
            # If no cycle, girth is infinity
            girth = float('inf')

        if girth >= 7:
            return list(edges)

