def is_3_colorable(n, edges):
    # Simple backtracking for 3-coloring
    color = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(3):
            can_color = True
            for v in range(n):
                if (u, v) in edges or (v, u) in edges:
                    if color[v] == c:
                        can_color = False
                        break
            if can_color:
                color[u] = c
                if solve(u + 1):
                    return True
                color[u] = -1
        return False
    return solve(0)

